// The golden file is generated by driving the upstream Editor with scripted
// input sequences and dumping the text, cursor, render, and expanded text.
// See tui/testdata/editor_corpus.json.

type editorGolden struct {
	values map[string]string
}

func loadEditorGolden(t *testing.T) *editorGolden {
	t.Helper()
	file, err := os.Open("testdata/editor_golden.txt")
	if err != nil {
		t.Fatalf("open golden: %v", err)
	}
	defer file.Close()
	values := map[string]string{}
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		parts := strings.SplitN(line, " => ", 2)
		if len(parts) != 2 {
			t.Fatalf("bad golden line %q", line)
		}
		values[strings.TrimPrefix(parts[0], "ed ")] = parts[1]
	}
	if err := scanner.Err(); err != nil {
		t.Fatalf("scan: %v", err)
	}
	return &editorGolden{values: values}
}

type editorSpec struct {
	Text     *string  `json:"text"`
	Inputs   []string `json:"inputs"`
	Width    int      `json:"width"`
	Rows     int      `json:"rows"`
	History  []string `json:"history"`
	Focused  bool     `json:"focused"`
	Expanded bool     `json:"expanded"`
	Options  *struct {
		PaddingX               int `json:"paddingX"`
		AutocompleteMaxVisible int `json:"autocompleteMaxVisible"`
	} `json:"options"`
}

type editorHost struct {
	rows int
}

func (h *editorHost) Rows() int                { return h.rows }
func (h *editorHost) RequestRender(force bool) {}

func editorTestTheme() EditorTheme {
	return EditorTheme{
		BorderColor: mdTag("bc"),
		SelectList: SelectListTheme{
			SelectedPrefix: mdTag("sp"),
			SelectedText:   mdTag("st"),
			Description:    mdTag("sd"),
			ScrollInfo:     mdTag("si"),
			NoMatch:        mdTag("sn"),
		},
	}
}

// TestEditorAgainstUpstreamGolden replays the upstream editor corpus.
func TestEditorAgainstUpstreamGolden(t *testing.T) {
	golden := loadEditorGolden(t)
	data, err := os.ReadFile("testdata/editor_corpus.json")
	if err != nil {
		t.Fatalf("read corpus: %v", err)
	}
	corpus := map[string]editorSpec{}
	if err := json.Unmarshal(data, &corpus); err != nil {
		t.Fatalf("parse corpus: %v", err)
	}

	labels := make([]string, 0, len(corpus))
	for label := range corpus {
		labels = append(labels, label)
	}
	sortStrings(labels)

	for _, label := range labels {
		spec := corpus[label]
		rows := spec.Rows
		if rows == 0 {
			rows = 10
		}
		host := &editorHost{rows: rows}
		options := EditorOptions{}
		if spec.Options != nil {
			options.PaddingX = spec.Options.PaddingX
			options.AutocompleteMaxVisible = spec.Options.AutocompleteMaxVisible
		}
		editor := NewEditor(host, editorTestTheme(), options)
		editor.SetFocused(spec.Focused)
		for _, entry := range spec.History {
			editor.AddToHistory(entry)
		}
		if spec.Text != nil {
			editor.SetText(*spec.Text)
		}
		for _, input := range spec.Inputs {
			switch {
			case strings.HasPrefix(input, "MOUSE:"):
				parts := strings.Split(input, ":")
				x, _ := strconv.Atoi(parts[1])
				y, _ := strconv.Atoi(parts[2])
				width, _ := strconv.Atoi(parts[3])
				editor.HandleMouse(TuiMouseEvent{
					Type: MouseClick, Button: MouseButtonLeft,
					X: x, Y: y, Width: width, Height: 10, ScreenX: x, ScreenY: y,
				})
			case strings.HasPrefix(input, "SETTEXT:"):
				editor.SetText(input[len("SETTEXT:"):])
			default:
				editor.HandleInput(input)
			}
		}

		width := spec.Width
		if width == 0 {
			width = 30
		}
		checkGolden(t, golden.values, label+" text", mustJSON(editor.GetText()))
		// Upstream cursors are UTF-16 code-unit offsets; the Go port uses byte
		// offsets, so the golden cursor is translated.
		wantCursor, ok := golden.values[label+" cursor"]
		if !ok {
			t.Fatalf("missing golden %q", label+" cursor")
		}
		cursorParts := strings.Split(wantCursor, ",")
		wantLine, _ := strconv.Atoi(cursorParts[0])
		wantColJS, _ := strconv.Atoi(cursorParts[1])
		line, col := editor.Cursor()
		lines := editor.GetLines()
		wantCol := wantColJS
		if wantLine >= 0 && wantLine < len(lines) {
			wantCol = jsOffsetToByteOffset(lines[wantLine], wantColJS)
		}
		if line != wantLine || col != wantCol {
			t.Fatalf("%s cursor: got %d,%d want %d,%d", label, line, col, wantLine, wantCol)
		}
		checkGolden(t, golden.values, label+" render@"+strconv.Itoa(width), normalizeSlice(editor.Render(width)))
		if spec.Expanded {
			checkGolden(t, golden.values, label+" expanded", mustJSON(editor.GetExpandedText()))
		}
	}
}

// normalizeSlice converts a nil slice into an empty one so JSON output matches
// upstream's empty arrays.
func normalizeSlice(lines []string) []string {
	if lines == nil {
		return []string{}
	}
	return lines
}

// Upstream measures a large paste in UTF-16 code units (String.length), so
// astral characters count as two.
func TestEditorPasteThresholdCountsUTF16Units(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	// 600 astral runes are 1200 UTF-16 units (> 1000) but only 600 runes.
	editor.handlePasteLocked(strings.Repeat("\U0001F600", 600))
	if got := editor.GetText(); !strings.Contains(got, "chars]") {
		t.Fatalf("paste was not collapsed to a marker: %q", got)
	}
}

// Mirrors first-occurrence start-marker removal in
// packages/tui/src/components/editor.ts, including an embedded marker that
// leaves its preceding bytes in the paste buffer.
func TestEditorBracketedPasteWithEmbeddedStartMarkerPreservesPrefix(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	editor.HandleInput("prefix\x1b[200~payload\x1b[201~")
	if got, want := editor.GetText(), "prefixpayload"; got != want {
		t.Fatalf("pasted text = %q, want %q", got, want)
	}
}

func TestEditorBracketedLargePasteAvoidsCopyingInput(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	pasted := strings.Repeat("plain text ", 24*1024)
	input := "\x1b[200~" + pasted + "\x1b[201~"

	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	editor.HandleInput(input)
	runtime.ReadMemStats(&after)

	if got := editor.GetExpandedText(); got != pasted {
		t.Fatalf("expanded paste length = %d, want %d", len(got), len(pasted))
	}
	allocated := after.TotalAlloc - before.TotalAlloc
	t.Logf("bracketed %d-byte input allocated %d bytes", len(input), allocated)
	if allocated > uint64(len(input))/4 {
		t.Fatalf("bracketed paste of %d bytes allocated %d bytes, want less than %d", len(input), allocated, len(input)/4)
	}
}

func TestEditorPasteFiltersControlBytesAndDecodesCSIu(t *testing.T) {
	// Port of packages/tui/src/components/editor.ts handlePaste.
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	editor.handlePasteLocked("a\x00b\r\nc\x1b[106;5uX\x1f")
	if got, want := editor.GetText(), "ab\nc\nX"; got != want {
		t.Fatalf("pasted text = %q, want %q", got, want)
	}
}

func TestEditorCleanLargePasteDoesNotCopyFilteredText(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	pasted := strings.Repeat("plain text ", 24*1024)

	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	editor.handlePasteLocked(pasted)
	runtime.ReadMemStats(&after)

	if got := editor.GetExpandedText(); got != pasted {
		t.Fatalf("expanded paste length = %d, want %d", len(got), len(pasted))
	}
	allocated := after.TotalAlloc - before.TotalAlloc
	t.Logf("clean %d-byte paste allocated %d bytes", len(pasted), allocated)
	if allocated > uint64(len(pasted))/4 {
		t.Fatalf("clean %d-byte paste allocated %d bytes, want less than %d", len(pasted), allocated, len(pasted)/4)
	}
}

// TestEditorSubmitReentrancy: the submit handler runs outside the
// editor lock, so it may call back into the editor without deadlocking.
func TestEditorSubmitReentrancy(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	var submitted []string
	editor.OnSubmit = func(text string) {
		submitted = append(submitted, text)
		// The interactive submit handler clears and reads the editor.
		editor.SetText("")
		_ = editor.GetText()
		editor.AddToHistory(text)
	}

	done := make(chan struct{})
	go func() {
		defer close(done)
		editor.SetText("hello")
		editor.HandleInput("\r")
	}()

	select {
	case <-done:
	case <-time.After(2 * time.Second):
		t.Fatal("HandleInput deadlocked in OnSubmit")
	}
	if len(submitted) != 1 || submitted[0] != "hello" {
		t.Fatalf("submitted = %v", submitted)
	}
	if editor.GetText() != "" {
		t.Fatalf("editor = %q", editor.GetText())
	}
}

// Mirrors packages/tui/src/word-navigation.ts: backward movement skips a
// contiguous punctuation run when the cursor is at its end.
func TestFindWordBackwardPunctuationRunDoesNotCopySegments(t *testing.T) {
	const segmentCount = 8192
	text := strings.Repeat("!", segmentCount)
	segments := make([]editorSegment, segmentCount)
	for index := range segments {
		segments[index] = editorSegment{Segment: "!", Index: index}
	}

	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	got := findWordBackwardSegments(len(text), segments)
	runtime.ReadMemStats(&after)

	if got != 0 {
		t.Fatalf("cursor = %d, want 0", got)
	}
	allocated := after.TotalAlloc - before.TotalAlloc
	t.Logf("backward navigation across %d segments allocated %d bytes", segmentCount, allocated)
	if allocated > uint64(segmentCount*4) {
		t.Fatalf("backward navigation across %d segments allocated %d bytes, want less than %d", segmentCount, allocated, segmentCount*4)
	}
}

// Mirrors packages/tui/src/word-navigation.ts findWordBackward: a word-like
// segment with punctuation leaves the cursor after its last punctuation rune.
func TestEditorWordNavigationDoesNotCopyRuneTables(t *testing.T) {
	text := "word." + strings.Repeat("x", 64*1024)
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	editor.SetText(text)
	editor.state.cursorCol = len(text)

	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	editor.moveWordBackwardsLocked()
	runtime.ReadMemStats(&after)

	if editor.state.cursorCol != len("word.") {
		t.Fatalf("cursor = %d, want %d", editor.state.cursorCol, len("word."))
	}
	allocated := after.TotalAlloc - before.TotalAlloc
	t.Logf("word navigation over %d bytes allocated %d bytes", len(text), allocated)
	if allocated > uint64(len(text))*2 {
		t.Fatalf("word navigation over %d bytes allocated %d bytes, want less than %d", len(text), allocated, len(text)*2)
	}
}

// The punctuation offset is a byte index, while the suffix may be UTF-8.
func TestFindWordBackwardAfterPunctuationAvoidsRuneSlice(t *testing.T) {
	text := "word." + strings.Repeat("x", 64*1024)
	segments := []editorSegment{{Segment: text, IsWordLike: true}}

	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	got := findWordBackwardSegments(len(text), segments)
	runtime.ReadMemStats(&after)

	if got != len("word.") {
		t.Fatalf("cursor = %d, want %d", got, len("word."))
	}
	unicodeText := "word.漢字"
	unicodeSegments := []editorSegment{{Segment: unicodeText, IsWordLike: true}}
	if got, want := findWordBackwardSegments(len(unicodeText), unicodeSegments), len("word."); got != want {
		t.Fatalf("Unicode cursor = %d, want %d", got, want)
	}
	allocated := after.TotalAlloc - before.TotalAlloc
	t.Logf("word movement over %d bytes allocated %d bytes", len(text), allocated)
	if allocated > uint64(len(text))/8 {
		t.Fatalf("word movement over %d bytes allocated %d bytes, want less than %d", len(text), allocated, len(text)/8)
	}
}

// The segmenter marks "e.g" word-like (its mid-word dot merges); the editor's
// word movement must use that flag, not recompute from the characters.
func TestEditorWordBackwardOverDottedWord(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	editor.SetText("e.g.")
	editor.state.cursorCol = len("e.g.")
	editor.moveWordBackwardsLocked()
	if editor.state.cursorCol != 3 {
		t.Fatalf("cursorCol = %d; want 3", editor.state.cursorCol)
	}
	editor.state.cursorCol = 0
	editor.moveWordForwardsLocked()
	if editor.state.cursorCol != 1 {
		t.Fatalf("forward cursorCol = %d; want 1", editor.state.cursorCol)
	}
}

// isInSlashCommandContext trims the full JS whitespace set.
func TestEditorSlashCommandContextUnicodeWhitespace(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	if !editor.isInSlashCommandContext("\u3000/cmd") {
		t.Fatal("ideographic space before slash should be a slash-command context")
	}
}

// History and submit trim with JS String.trim (U+FEFF is whitespace, U+0085 is
// not), not strings.TrimSpace.
func TestEditorUsesJSTrim(t *testing.T) {
	editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
	editor.AddToHistory("\uFEFF")
	if len(editor.history) != 0 {
		t.Fatalf("U+FEFF should not be recorded: %q", editor.history)
	}
	editor.AddToHistory("\u0085")
	if len(editor.history) != 1 || editor.history[0] != "\u0085" {
		t.Fatalf("U+0085 should be recorded: %q", editor.history)
	}

	submitted := "unset"
	editor.OnSubmit = func(text string) { submitted = text }
	editor.SetText("\uFEFF")
	editor.HandleInput("\r")
	if submitted != "" {
		t.Fatalf("submit of U+FEFF = %q; want empty", submitted)
	}
}

// TestEditorSanitizesTextOnEntry pins the editor against terminal control
// injection through its buffer (D452). The editor draws its buffer,
// and text can arrive from a paste or a completion rather than a keystroke, which
// never carries a raw escape byte. Reference: pi v1.5.0 f9a26365 editor.ts
// inserts the text it is given, as the port did.
func TestEditorSanitizesTextOnEntry(t *testing.T) {
	payload := "hi \x1b[2J\x1b]52;c;cGF3bmVk\x07 there"

	// A completion is the path that carried a file name from disk into the
	// buffer: the provider returns whole lines, so the result is installed by the
	// same guard the Tab and list paths use.
	completion := CompletionResult{Lines: []string{payload}, CursorLine: 0, CursorCol: len(payload)}
	cases := map[string]func(*Editor){
		"SetText":            func(e *Editor) { e.SetText(payload) },
		"InsertTextAtCursor": func(e *Editor) { e.InsertTextAtCursor(payload) },
		"paste":              func(e *Editor) { e.handlePasteLocked(payload) },
		"completion":         func(e *Editor) { e.applyCompletionResultLocked(completion) },
	}
	for name, fill := range cases {
		t.Run(name, func(t *testing.T) {
			editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
			fill(editor)
			for _, line := range editor.Render(100) {
				if strings.Contains(line, "\x1b[2J") || strings.Contains(line, "\x1b]52") {
					t.Fatalf("the editor drew a stored sequence: %q", line)
				}
			}
		})
	}
}

// D281: pi v1.4.0 (4a080252), components/editor.ts wordWrapLine recurses on
// one over-wide grapheme without reducing it. A two-column editor leaves one
// layout column, so a CJK glyph crashes rendering. Re-exec contains Go's fatal
// stack overflow; the small child-only stack limit makes the regression fast.
func TestEditorRendersWideGraphemeInNarrowTerminal(t *testing.T) {
	const probeEnv = "PIER_TEST_EDITOR_NARROW_GRAPHEME"
	if mode := os.Getenv(probeEnv); mode != "" {
		debug.SetMaxStack(128 * 1024)
		editor := NewEditor(nil, EditorTheme{}, EditorOptions{})
		editor.SetText("界")
		width := 20
		if mode == "narrow" {
			width = 2
		}
		if lines := editor.Render(width); len(lines) < 3 {
			t.Fatalf("editor render returned no content: %q", lines)
		}
		if editor.GetText() != "界" {
			t.Fatal("narrow rendering changed the editor text")
		}
		return
	}
	for _, mode := range []string{"control", "narrow"} {
		t.Run(mode, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancel()
			command := exec.CommandContext(ctx, os.Args[0], "-test.run=^TestEditorRendersWideGraphemeInNarrowTerminal$", "-test.timeout=4s")
			command.Env = append(os.Environ(), probeEnv+"="+mode)
			if output, err := command.CombinedOutput(); err != nil {
				if len(output) > 2000 {
					output = output[:2000]
				}
				t.Fatalf("editor render did not complete: %v\n%s", err, output)
			}
		})
	}
}

// pi v1.4.0 (4a080252), components/editor.ts expandPasteMarkers passes a
// replacement function to String.replace, so dollar sequences remain literal.
func TestEditorLargePastePreservesDollarTextOnSubmit(t *testing.T) {
	previous := GetKeybindings()
	SetKeybindings(NewKeybindingsManager(TUIKeybindings, nil))
	t.Cleanup(func() { SetKeybindings(previous) })
	editor := NewEditor(nil, EditorTheme{}, EditorOptions{})
	paste := strings.Repeat("line\n", 10) + `echo "$HOME" "$1" "${name}" "$$"`
	editor.HandleInput("\x1b[200~" + paste + "\x1b[201~")
	if got := editor.GetExpandedText(); got != paste {
		t.Errorf("expanded paste changed dollar sequences: got %q, want %q", got, paste)
	}
	var submitted string
	editor.OnSubmit = func(text string) { submitted = text }
	editor.HandleInput("\r")
	if submitted != paste {
		t.Errorf("submitted paste changed dollar sequences: got %q, want %q", submitted, paste)
	}
}

// Upstream expands pastes by iterating its paste Map, whose order is insertion
// order; Go's map order is random. The order matters because a paste body can
// itself carry a later paste's marker: expanding the higher ID first leaves
// that marker sitting in the text while its replacement is a no-op.
func TestPasteExpansionOrderIsInsertionOrder(t *testing.T) {
	editor := NewEditor(nil, EditorTheme{}, EditorOptions{})
	editor.pastes[3] = "third"
	editor.pastes[1] = "first contains [paste #2 6 chars]"
	editor.pastes[2] = "second"
	editor.pasteCounter = 3

	got := editor.pasteExpansionOrder()
	want := []int{1, 2, 3}
	if len(got) != len(want) {
		t.Fatalf("order = %v, want %v", got, want)
	}
	for index := range want {
		if got[index] != want[index] {
			t.Fatalf("order = %v, want %v", got, want)
		}
	}
}

type undoStepHost struct{}

func (undoStepHost) Rows() int          { return 24 }
func (undoStepHost) RequestRender(bool) {}

// isWhitespaceChar in pi v1.5.0 (f9a26365) packages/tui/src/utils.ts is
// `/\s/.test(char)`: any string that contains a whitespace character counts.
// The editor's undo coalescing uses it, so an insertion whose text contains a
// space starts a new undo unit, while one without whitespace coalesces into the
// current typing unit. Pier tested "every rune is whitespace", which is only
// true for a lone space, so a multi-character insertion could join the previous
// unit and one undo removed an extra typing step. Reference behaviour, with the
// input string inserted through HandleInput and then ctrl+- (undo):
//
//	["a", "first message", undo] -> "a" (the insert is its own unit)
//	["a", "bc", undo]            -> ""  (coalesced with "a")
//	["a", " b", undo]            -> "a"
func TestEditorMultiCharacterInsertHasItsOwnUndoUnit(t *testing.T) {
	for _, test := range []struct {
		keys []string
		want string
	}{
		{[]string{"a", "first message", "\x1f"}, "a"},
		{[]string{"a", "bc", "\x1f"}, ""},
		{[]string{"a", " b", "\x1f"}, "a"},
		{[]string{"漢", "first message", "\x1f"}, "漢"},
	} {
		editor := NewEditor(undoStepHost{}, EditorTheme{}, EditorOptions{})
		for _, key := range test.keys {
			editor.HandleInput(key)
		}
		if got := editor.GetText(); got != test.want {
			t.Errorf("keys %q: text %q, want %q", test.keys, got, test.want)
		}
	}
}

// Upstream's sticky column is cursorCol - startCol over JavaScript strings, a
// UTF-16 offset, so vertical moves keep the code-unit column rather than the
// byte offset Go stores (pi v1.5.0 packages/tui/src/components/editor.ts
// moveToVisualLine). Expected cursors come from the upstream Editor and are
// translated to byte offsets.
func TestEditorVerticalMovesKeepTheUTF16Column(t *testing.T) {
	for _, tc := range []struct {
		name      string
		text      string
		inputs    []string
		line, col int
	}{
		// "c😀" ends at unit 3 (byte 5); PageUp lands at "a  |  b".
		{"page up from emoji", "", []string{"\x1b[200~a\tb\r\nc\x1b[201~", "😀", "\x1b[5~"}, 0, 3},
		{"up from emoji", "abcdef\nc😀", []string{"\x1b[A"}, 0, 3},
		// Unit 3 is inside the two-unit "é́", which snaps to its start (byte 4).
		{"up into combining marks", "é́é́é́é́\nxyz", []string{"\x1b[A"}, 0, 4},
		// "é́é́" ends at unit 4 (byte 8).
		{"up from combining marks", "abcdef\né́é́", []string{"\x1b[A"}, 0, 4},
	} {
		editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
		editor.SetFocused(true)
		if tc.text != "" {
			editor.SetText(tc.text)
		}
		for _, input := range tc.inputs {
			editor.HandleInput(input)
		}
		editor.Render(30)
		if line, col := editor.Cursor(); line != tc.line || col != tc.col {
			t.Errorf("%s: cursor %d,%d; want %d,%d", tc.name, line, col, tc.line, tc.col)
		}
	}
}

// pi v1.4.0 (4a080252), packages/tui/src/word-navigation.ts: findWordBackward
// and findWordForward segment only the text before or after the cursor, so a
// cursor inside a word moves to that word's edge. Segmenting the whole line
// made the backward move land before the word start (a negative column, which
// the next edit or forward delete sliced with) and left the forward move with
// nothing to advance over (CR-210).
func TestEditorWordNavigationInsideWord(t *testing.T) {
	newEditor := func(text string) *Editor {
		editor := NewEditor(&editorHost{rows: 10}, editorTestTheme(), EditorOptions{})
		editor.SetFocused(true)
		editor.SetText(text)
		return editor
	}
	// press sends inputs and then types X so the cursor position is observable
	// through the text.
	press := func(editor *Editor, inputs ...string) string {
		for _, input := range inputs {
			editor.HandleInput(input)
		}
		return editor.GetText()
	}

	t.Run("backward stops at word start", func(t *testing.T) {
		editor := newEditor("ab")
		if got := press(editor, "\x1b[D", "\x1b[1;5D", "X"); got != "Xab" {
			t.Fatalf("text = %q, want %q", got, "Xab")
		}
	})

	t.Run("backward then forward delete", func(t *testing.T) {
		editor := newEditor("ab")
		if got := press(editor, "\x1b[D", "\x1b[1;5D", "\x1b[3~"); got != "b" {
			t.Fatalf("text = %q, want %q", got, "b")
		}
	})

	t.Run("forward stops at word end", func(t *testing.T) {
		editor := newEditor("abcd")
		// Home, then right once: the cursor sits inside the word.
		if got := press(editor, "\x1b[H", "\x1b[C", "\x1b[1;5C", "X"); got != "abcdX" {
			t.Fatalf("text = %q, want %q", got, "abcdX")
		}
	})

	t.Run("forward from punctuation boundary", func(t *testing.T) {
		editor := newEditor("a.b")
		if got := press(editor, "\x1b[D", "\x1b[D", "\x1b[1;5C", "X"); got != "a.Xb" {
			t.Fatalf("text = %q, want %q", got, "a.Xb")
		}
	})

	t.Run("backward inside a later word", func(t *testing.T) {
		editor := newEditor("foo bar")
		if got := press(editor, "\x1b[D", "\x1b[D", "\x1b[1;5D", "X"); got != "foo Xbar" {
			t.Fatalf("text = %q, want %q", got, "foo Xbar")
		}
	})

	t.Run("cursor never goes negative on multibyte lines", func(t *testing.T) {
		editor := newEditor("a\u0301b")
		editor.HandleInput("\x1b[H")
		editor.HandleInput("\x1b[1;5C")
		editor.HandleInput("X")
		if got := editor.GetText(); got != "a\u0301bX" {
			t.Fatalf("text = %q, want %q", got, "a\u0301bX")
		}
	})
}

// Upstream's UndoStack.pop() in packages/tui/src/undo-stack.ts removes the
// popped element from the array. The Go stack must likewise release references
// after undo, so large snapshots do not stay live in unused slice capacity.
func TestUndoStackPopReleasesPoppedSnapshot(t *testing.T) {
	value := "large editor snapshot"
	var stack UndoStack[*string]
	stack.Push(&value)

	popped, ok := stack.Pop()
	if !ok || popped != &value {
		t.Fatalf("Pop() = (%p, %v), want (%p, true)", popped, ok, &value)
	}
	if retained := stack.stack[:cap(stack.stack)]; retained[0] != nil {
		t.Fatalf("popped snapshot remains retained in stack capacity: %p", retained[0])
	}
}

// D471: a single-line input draws its value directly, and a paste is the one
// path that can carry escape sequences into it. The reference's input.ts pastes
// what it is given; pier strips them on entry, as the editor does (D452), so a
// pasted string cannot write the clipboard, retitle the window or move the
// cursor.
func TestInputPasteCannotEmitTerminalControls(t *testing.T) {
	input := NewInput(InputOptions{})
	input.HandleInput("\x1b[200~" + "\x1b]52;c;aGk=\x07title\x1b[2J" + "hello" + "\x1b[201~")
	value := input.Value()
	if strings.ContainsAny(value, "\x1b\x07") {
		t.Fatalf("value = %q, want no control characters", value)
	}
	if !strings.Contains(value, "hello") {
		t.Fatalf("value = %q, want the pasted text kept", value)
	}

	// Typed text still reaches the value, so the paste path is the only change.
	input = NewInput(InputOptions{})
	input.HandleInput("abc")
	if got := input.Value(); got != "abc" {
		t.Fatalf("value = %q, want typed text", got)
	}
}

// TestWordNavigationNormalizesItsCursor pins A509. The functions take UTF-16
// code-unit offsets; a cursor inside a surrogate pair is not a boundary, and
// the pin would answer from a lone surrogate, which Go cannot represent. Pier
// normalizes such a cursor to the pair's end and always returns a valid offset.
// Reference: pi v1.5.0 (f9a26365) packages/tui/src/word-navigation.ts.
func TestWordNavigationNormalizesItsCursor(t *testing.T) {
	texts := []string{
		"🇯🇵 flag",
		"👨‍👩‍👧‍👦 fam",
		"日本語 テキスト",
		"a🇯🇵b",
		"😀",
		"plain ascii words",
	}
	for _, text := range texts {
		limit := jsLength(text)
		for cursor := 0; cursor <= limit; cursor++ {
			backward := FindWordBackward(text, cursor)
			if backward < 0 || backward > cursor {
				t.Errorf("FindWordBackward(%q, %d) = %d, want in [0,%d]", text, cursor, backward, cursor)
			}
			forward := FindWordForward(text, cursor)
			if forward < cursor || forward > limit {
				t.Errorf("FindWordForward(%q, %d) = %d, want in [%d,%d]", text, cursor, forward, cursor, limit)
			}
		}
	}

	// A cursor inside either pair answers like the pair's end; offsets 5 and up
	// are ordinary boundaries of the words that follow.
	for _, cursor := range []int{1, 3} {
		backward := FindWordBackward("🇯🇵 flag", cursor)
		if backward != FindWordBackward("🇯🇵 flag", 2) {
			t.Errorf("FindWordBackward at mid-pair cursor %d = %d, want the normalized value %d",
				cursor, backward, FindWordBackward("🇯🇵 flag", 2))
		}
	}
	if got := FindWordBackward("🇯🇵 flag", 1); got != 0 {
		t.Errorf("FindWordBackward(\"🇯🇵 flag\", 1) = %d, want 0", got)
	}
}
